import React, { useState } from 'react';

export default function ArticleCard({ article, index }) {
  const [open, setOpen] = useState(false);

  function timeAgo(dateStr) {
    if (!dateStr) return '';
    const diff = Date.now() - new Date(dateStr).getTime();
    const hours = Math.floor(diff / 3600000);
    if (hours < 1) return 'Just now';
    if (hours < 24) return hours + 'h ago';
    return Math.floor(hours / 24) + 'd ago';
  }

  const sentimentColor =
    article.sentiment === 'positive' ? '#27ae60' :
    article.sentiment === 'negative' ? '#c0392b' : '#7f8c8d';

  const sentimentLabel =
    article.sentiment === 'positive' ? '↑ Positive' :
    article.sentiment === 'negative' ? '↓ Negative' : '— Neutral';

  return (
    <div
      className="fade-in"
      style={{
        animationDelay: index * 0.04 + 's',
        borderTop: '1px solid #e0d9ce',
        paddingTop: '16px',
        paddingBottom: '20px',
      }}
    >
      {article.image_url && index === 0 && (
        <img
          src={article.image_url}
          alt=""
          style={{
            width: '100%',
            height: '200px',
            objectFit: 'cover',
            marginBottom: '12px',
            display: 'block',
          }}
          onError={function(e) { e.target.style.display = 'none'; }}
        />
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
        <span style={{ fontSize: '10px', fontWeight: '600', letterSpacing: '1.5px', textTransform: 'uppercase', color: '#c0392b' }}>
          {article.category}
        </span>
        <div style={{ display: 'flex', gap: '10px' }}>
          <span style={{ fontSize: '10px', color: '#7f8c8d' }}>{timeAgo(article.published_at)}</span>
          <span style={{ fontSize: '10px', fontWeight: '600', color: sentimentColor }}>{sentimentLabel}</span>
        </div>
      </div>


      <a  href={article.url}
        target="_blank"
        rel="noreferrer"
        style={{
          display: 'block',
          fontFamily: 'Lora, serif',
          fontSize: index === 0 ? '22px' : '17px',
          fontWeight: '600',
          color: '#1a1a1a',
          lineHeight: '1.3',
          marginBottom: '6px',
        }}
      >
        {article.title}
      </a>

      <p style={{ fontSize: '11px', color: '#7f8c8d', marginBottom: '10px', fontStyle: 'italic' }}>
        {article.source_name}
      </p>

      {article.summary && (
        <p style={{ fontSize: '13px', color: '#4a4a4a', lineHeight: '1.7', marginBottom: '10px', borderLeft: '2px solid #c0392b', paddingLeft: '10px' }}>
          {article.summary}
        </p>
      )}

      {article.key_insights && article.key_insights.length > 0 && (
        <div>
          <button
            onClick={function() { setOpen(!open); }}
            style={{
              background: 'none',
              border: 'none',
              padding: '0',
              fontSize: '11px',
              color: '#2c3e50',
              fontWeight: '600',
              letterSpacing: '0.5px',
              textTransform: 'uppercase',
              cursor: 'pointer',
              textDecoration: 'underline',
            }}
          >
            {open ? 'Hide insights' : 'Key Insights (' + article.key_insights.length + ')'}
          </button>
          {open && (
            <ul style={{ margin: '8px 0 0 0', paddingLeft: '16px' }}>
              {article.key_insights.map(function(ins, i) {
                return (
                  <li key={i} style={{ fontSize: '12px', color: '#4a4a4a', lineHeight: '1.6', marginBottom: '3px' }}>
                    {ins}
                  </li>
                );
              })}
            </ul>
          )}
        </div>
      )}
    </div>
  );
}
